package com.cowave.search.dictionary.model

import com.fasterxml.jackson.annotation.JsonIgnoreProperties
import java.time.Instant

@JsonIgnoreProperties(ignoreUnknown = true)
class Dictionary(
    val id: String?,
    val keyword: String?,
    val type: Type,
    val value: String?,
    val createdTime: Instant,
    val updatedTime: Instant,
) {
    companion object {
        fun of(
            keyword: String?,
            type: Type,
            value: String?,
            createdTime: Instant,
            updatedTime: Instant,
        ): Dictionary =
            Dictionary(
                id = null,
                keyword = keyword,
                type = type,
                value = value,
                createdTime = createdTime,
                updatedTime = updatedTime,
            )
    }
}

package com.cowave.search.dictionary.service

import co.elastic.clients.transport.rest5_client.low_level.Request
import co.elastic.clients.transport.rest5_client.low_level.Rest5Client
import com.cowave.search.dictionary.dto.AllTypesCountResponse
import com.cowave.search.dictionary.dto.AllTypesLastModifiedResponse
import com.cowave.search.dictionary.dto.CompileResult
import com.cowave.search.dictionary.dto.CursorPagedResponse
import com.cowave.search.dictionary.dto.SearchColumn
import com.cowave.search.dictionary.dto.SortType
import com.cowave.search.dictionary.dto.TypeCountResponse
import com.cowave.search.dictionary.dto.TypeLastModifiedResponse
import com.cowave.search.dictionary.model.Dictionary
import com.cowave.search.dictionary.model.Type
import com.cowave.search.utils.DictionaryBinaryCompile
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

@Service
class DictionaryService(
    val dictionaryRepository: DictionaryRepository,
    val dictionaryBinaryCompile: DictionaryBinaryCompile,
    val restClient: Rest5Client,
) {
    private val logger = LoggerFactory.getLogger(DictionaryService::class.java)

    fun search(
        type: Type,
        size: Int,
        searchColumn: SearchColumn = SearchColumn.ALL,
        word: String? = null,
        isMatch: Boolean = false,
        cursor: String? = null,
        sortType: SortType = SortType.UPDATED,
    ): CursorPagedResponse<Dictionary> {
        val searchAfterList = cursor?.split(CURSOR_DELIMITER)
        val result =
            dictionaryRepository.search(
                type = type,
                size = size,
                searchColumn = searchColumn,
                value = word,
                isMatch = isMatch,
                searchAfter = searchAfterList,
                sortType = sortType,
            )

        return CursorPagedResponse(
            items = result.items,
            total = result.total,
            cursor = result.searchAfter?.joinToString(CURSOR_DELIMITER),
            hasNext = result.hasNext,
        )
    }

    fun create(
        keyword: String?,
        type: Type,
        value: String?,
    ) {
        dictionaryRepository.insert(keyword, type, value)
    }

    fun update(
        id: String,
        keyword: String,
        type: Type,
        value: String?,
    ) {
        dictionaryRepository.update(id, keyword, type, value)
    }

    fun delete(id: String) {
        dictionaryRepository.delete(id)
    }

    fun countByType(type: Type): Long = dictionaryRepository.countByType(type)

    fun compile(type: Type): CompileResult {
        val result = compileWithoutReload(type)
        reloadDictionary()
        return result
    }

    fun compileAll(): List<CompileResult> {
        val results: List<CompileResult> = Type.entries.map { compileWithoutReload(it) }
        reloadDictionary()
        return results
    }

    private fun compileWithoutReload(type: Type): CompileResult {
        val dictionaries = dictionaryRepository.findAllByType(type)
        val pairs = dictionaries.map { it.keyword to it.value }
        val outputFile = dictionaryBinaryCompile.compileToConfiguredPath(pairs, type)

        return CompileResult(
            type = type,
            count = dictionaries.size,
            filePath = outputFile.absolutePath,
            fileSize = outputFile.length(),
        )
    }

    private fun reloadDictionary() {
        logger.info("Reloading dictionary in Elasticsearch...")
        val request = Request("POST", "/_analysis-product-name/reload-dict")
        val response = restClient.performRequest(request)
        val statusCode = response.statusCode
        if (statusCode !in 200..299) {
            throw RuntimeException("Failed to reload dictionary: HTTP $statusCode")
        }
        logger.info("Dictionary reload completed successfully")
    }

    fun getLastModifiedByType(type: Type): TypeLastModifiedResponse {
        val (lastModified, count) = dictionaryRepository.findLastModifiedByType(type)
        return TypeLastModifiedResponse(
            type = type,
            lastModified = lastModified,
            count = count,
        )
    }

    fun getAllTypesLastModified(): AllTypesLastModifiedResponse {
        val allTypesData = dictionaryRepository.findLastModifiedForAllTypes()
        val items =
            Type.entries.map { type ->
                val (lastModified, count) = allTypesData[type] ?: Pair(null, 0L)
                TypeLastModifiedResponse(
                    type = type,
                    lastModified = lastModified,
                    count = count,
                )
            }
        return AllTypesLastModifiedResponse(items)
    }

    fun getAllTypesCounts(): AllTypesCountResponse {
        val allTypesCounts = dictionaryRepository.countAllTypes()
        val items =
            Type.entries.map { type ->
                TypeCountResponse(
                    type = type,
                    count = allTypesCounts[type] ?: 0L,
                )
            }
        val totalCount = items.sumOf { it.count }
        return AllTypesCountResponse(items, totalCount)
    }

    companion object {
        private const val CURSOR_DELIMITER = "|"
    }
}

package com.cowave.search.dictionary.controller

import com.cowave.search.dictionary.dto.AllTypesCountResponse
import com.cowave.search.dictionary.dto.AllTypesLastModifiedResponse
import com.cowave.search.dictionary.dto.CompileResult
import com.cowave.search.dictionary.dto.CreateDictionaryRequest
import com.cowave.search.dictionary.dto.CursorPagedResponse
import com.cowave.search.dictionary.dto.SearchColumn
import com.cowave.search.dictionary.dto.SortType
import com.cowave.search.dictionary.dto.TypeCountResponse
import com.cowave.search.dictionary.dto.TypeLastModifiedResponse
import com.cowave.search.dictionary.dto.UpdateDictionaryRequest
import com.cowave.search.dictionary.model.Dictionary
import com.cowave.search.dictionary.model.Type
import com.cowave.search.dictionary.service.DictionaryService
import org.springframework.http.HttpStatus
import org.springframework.web.bind.annotation.DeleteMapping
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.PutMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.ResponseStatus
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/dictionaries")
class DictionaryController(
    private val dictionaryService: DictionaryService,
) {
    /**
     * 사전 조회/검색 통합 API
     * - word가 없으면 전체 조회
     * - word가 있으면 검색 (searchColumn에 따라 대상 필드 결정)
     */
    @GetMapping("/{type}")
    fun getDictionary(
        @PathVariable type: Type,
        @RequestParam(defaultValue = "20") size: Int,
        @RequestParam(required = false) cursor: String?,
        @RequestParam(defaultValue = "UPDATED") sort: SortType,
        @RequestParam(defaultValue = "ALL") searchColumn: SearchColumn,
        @RequestParam(required = false) word: String?,
        @RequestParam(defaultValue = "false") isMatch: Boolean,
    ): CursorPagedResponse<Dictionary> =
        dictionaryService.search(
            type = type,
            size = size,
            searchColumn = searchColumn,
            word = word,
            isMatch = isMatch,
            cursor = cursor,
            sortType = sort,
        )

    @GetMapping("/{type}/count")
    fun countByType(
        @PathVariable type: Type,
    ): TypeCountResponse = TypeCountResponse(type, dictionaryService.countByType(type))

    @GetMapping("/{type}/last-modified")
    fun getLastModifiedByType(
        @PathVariable type: Type,
    ): TypeLastModifiedResponse = dictionaryService.getLastModifiedByType(type)

    @GetMapping("/last-modified")
    fun getAllTypesLastModified(): AllTypesLastModifiedResponse = dictionaryService.getAllTypesLastModified()

    @GetMapping("/count")
    fun getAllTypesCounts(): AllTypesCountResponse = dictionaryService.getAllTypesCounts()

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    fun create(
        @RequestBody request: CreateDictionaryRequest,
    ) {
        dictionaryService.create(request.keyword, request.type, request.value)
    }

    @PutMapping("/{id}")
    fun update(
        @PathVariable id: String,
        @RequestBody request: UpdateDictionaryRequest,
    ) {
        dictionaryService.update(id, request.keyword, request.type, request.value)
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun delete(
        @PathVariable id: String,
    ) {
        dictionaryService.delete(id)
    }

    @PostMapping("/compile/{type}")
    fun compile(
        @PathVariable type: Type,
    ): CompileResult = dictionaryService.compile(type)

    @PostMapping("/compile")
    fun compileAll(): List<CompileResult> = dictionaryService.compileAll()
}

package com.cowave.search.dictionary.infrastructure

import co.elastic.clients.elasticsearch.ElasticsearchClient
import co.elastic.clients.elasticsearch._types.FieldValue
import co.elastic.clients.elasticsearch._types.SortOptions
import co.elastic.clients.elasticsearch._types.SortOrder
import co.elastic.clients.elasticsearch._types.query_dsl.BoolQuery
import co.elastic.clients.elasticsearch._types.query_dsl.Query
import com.cowave.search.dictionary.dto.SearchColumn
import com.cowave.search.dictionary.dto.SortType
import com.cowave.search.dictionary.model.Dictionary
import com.cowave.search.dictionary.model.Type
import com.cowave.search.dictionary.service.DictionaryRepository
import com.cowave.search.domain.document.SearchAfterResult
import org.springframework.stereotype.Repository
import java.time.Instant

@Repository
class DictionaryRepositoryImpl(
    val esClient: ElasticsearchClient,
) : DictionaryRepository {
    override fun insert(
        keyword: String?,
        type: Type,
        value: String?,
    ) {
        esClient.index {
            it.index(DICTIONARY_INDEX)
            it.document(
                Dictionary.of(
                    keyword = keyword,
                    type = type,
                    value = value,
                    createdTime = Instant.now(),
                    updatedTime = Instant.now(),
                ),
            )
        }
    }

    override fun update(
        id: String,
        keyword: String,
        type: Type,
        value: String?,
    ) {
        esClient.update(
            {
                it
                    .index(DICTIONARY_INDEX)
                    .id(id)
                    .doc(
                        mapOf(
                            "keyword" to keyword,
                            "value" to value,
                            "updatedTime" to Instant.now(),
                        ),
                    )
            },
            Dictionary::class.java,
        )
    }

    override fun delete(id: String) {
        esClient.delete {
            it.index(DICTIONARY_INDEX).id(id)
        }
    }

    override fun search(
        type: Type,
        size: Int,
        searchColumn: SearchColumn,
        value: String?,
        isMatch: Boolean,
        searchAfter: List<String>?,
        sortType: SortType,
    ): SearchAfterResult<Dictionary> {
        val sortQuery =
            when (sortType) {
                SortType.UPDATED -> searchAfterSortQuery()
                SortType.KEYWORD -> keywordSearchAfterSortQuery(type)
            }

        val response =
            esClient.search(
                { s ->
                    s
                        .index(DICTIONARY_INDEX)
                        .trackTotalHits { it.enabled(true) }
                        .query { q ->
                            q.bool { b ->
                                // type 필터 (항상 적용)
                                b.filter { f ->
                                    f.term { t ->
                                        t
                                            .field("type")
                                            .value { v -> v.stringValue(type.toString()) }
                                    }
                                }
                                // 검색어가 있을 때만 검색 쿼리 추가
                                if (value != null) {
                                    addSearchQuery(b, searchColumn, value, isMatch)
                                }
                                b
                            }
                        }.size(size)
                        .sort(sortQuery)
                        .apply {
                            searchAfter?.let { sa ->
                                searchAfter(sa.map { FieldValue.of(it) })
                            }
                        }
                },
                Dictionary::class.java,
            )

        val hits = response.hits().hits()
        val items =
            hits.mapNotNull { hit ->
                hit.id()?.let { id ->
                    hit.source()?.let { Dictionary(id, it.keyword, it.type, it.value, it.createdTime, it.updatedTime) }
                }
            }
        val total = response.hits().total()?.value() ?: 0L
        val nextSearchAfter =
            hits.lastOrNull()?.sort()?.map { fieldValue ->
                fieldValue._get().toString()
            }
        val hasNext = hits.size == size && nextSearchAfter != null

        return SearchAfterResult(items, total, nextSearchAfter, hasNext)
    }

    /**
     * 검색 쿼리를 BoolQuery에 추가
     */
    private fun addSearchQuery(
        boolQuery: BoolQuery.Builder,
        searchColumn: SearchColumn,
        value: String,
        isMatch: Boolean,
    ) {
        val fields =
            when (searchColumn) {
                SearchColumn.ALL -> listOf("keyword", "value")
                SearchColumn.KEYWORD -> listOf("keyword")
                SearchColumn.VALUE -> listOf("value")
            }

        val shouldQueries =
            fields.map { field ->
                if (isMatch) {
                    Query.of { q ->
                        q.match { m ->
                            m.field(field)
                            m.query { qv -> qv.stringValue(value) }
                        }
                    }
                } else {
                    Query.of { q ->
                        q.wildcard { w ->
                            w.field(field)
                            w.value("*$value*")
                        }
                    }
                }
            }

        boolQuery.should(shouldQueries)
        boolQuery.minimumShouldMatch("1")
    }

    override fun findAllByType(type: Type): List<Dictionary> {
        val allResults = mutableListOf<Dictionary>()
        var searchAfter: List<FieldValue>? = null
        val batchSize = 10000

        do {
            val response =
                esClient.search(
                    { s ->
                        s
                            .index(DICTIONARY_INDEX)
                            .query { q ->
                                q.term { t ->
                                    t
                                        .field("type")
                                        .value { v -> v.stringValue(type.toString()) }
                                }
                            }.size(batchSize)
                            .sort { so ->
                                so.field { f ->
                                    f.field("createdTime").order(SortOrder.Asc)
                                }
                            }.apply {
                                searchAfter?.let { sa -> searchAfter(sa) }
                            }
                    },
                    Dictionary::class.java,
                )

            val hits = response.hits().hits()
            hits.mapNotNull { it.source() }.let { allResults.addAll(it) }

            searchAfter = hits.lastOrNull()?.sort()
        } while (searchAfter != null && response.hits().hits().size == batchSize)

        return allResults
    }

    override fun findLastModifiedByType(type: Type): Pair<Instant?, Long> {
        val response =
            esClient.search(
                { s ->
                    s
                        .index(DICTIONARY_INDEX)
                        .size(0) // We only need aggregation results, not documents
                        .query { q ->
                            q.term { t ->
                                t.field("type").value(type.name)
                            }
                        }.aggregations("max_updated_time") { agg ->
                            agg.max { m -> m.field("updatedTime") }
                        }
                },
                Dictionary::class.java,
            )

        val total = response.hits().total()?.value() ?: 0L
        val maxAgg = response.aggregations()["max_updated_time"]?.max()
        // ES returns NaN for empty aggregation results
        val lastModified =
            maxAgg?.value()?.takeIf { !it.isNaN() }?.let {
                Instant.ofEpochMilli(it.toLong())
            }

        return Pair(lastModified, total)
    }

    override fun findLastModifiedForAllTypes(): Map<Type, Pair<Instant?, Long>> {
        val response =
            esClient.search(
                { s ->
                    s
                        .index(DICTIONARY_INDEX)
                        .size(0) // We only need aggregation results
                        .aggregations("by_type") { agg ->
                            agg
                                .terms { t ->
                                    t.field("type").size(Type.entries.size)
                                }.aggregations("max_updated_time") { subAgg ->
                                    subAgg.max { m -> m.field("updatedTime") }
                                }
                        }
                },
                Dictionary::class.java,
            )

        val byTypeAgg = response.aggregations()["by_type"]?.sterms()
        val resultMap = mutableMapOf<Type, Pair<Instant?, Long>>()

        // Initialize all types with null/0
        Type.entries.forEach { type ->
            resultMap[type] = Pair(null, 0L)
        }

        // Update with actual values from aggregation
        byTypeAgg?.buckets()?.array()?.forEach { bucket ->
            val typeName = bucket.key().stringValue()
            val type = Type.entries.find { it.name == typeName }
            if (type != null) {
                val count = bucket.docCount()
                val maxAgg = bucket.aggregations()["max_updated_time"]?.max()
                val lastModified =
                    maxAgg?.value()?.takeIf { !it.isNaN() }?.let {
                        Instant.ofEpochMilli(it.toLong())
                    }
                resultMap[type] = Pair(lastModified, count)
            }
        }

        return resultMap
    }

    override fun countByType(type: Type): Long =
        esClient
            .count {
                it
                    .index(DICTIONARY_INDEX)
                    .query { q ->
                        q.term { t ->
                            t.field("type").value(type.name)
                        }
                    }
            }.count()

    override fun countAllTypes(): Map<Type, Long> {
        val response =
            esClient.search(
                { s ->
                    s
                        .index(DICTIONARY_INDEX)
                        .size(0) // We only need aggregation results
                        .aggregations("by_type") { agg ->
                            agg.terms { t ->
                                t.field("type").size(Type.entries.size)
                            }
                        }
                },
                Dictionary::class.java,
            )

        val byTypeAgg = response.aggregations()["by_type"]?.sterms()
        val resultMap = mutableMapOf<Type, Long>()

        // Initialize all types with 0
        Type.entries.forEach { type ->
            resultMap[type] = 0L
        }

        // Update with actual values from aggregation
        byTypeAgg?.buckets()?.array()?.forEach { bucket ->
            val typeName = bucket.key().stringValue()
            val type = Type.entries.find { it.name == typeName }
            if (type != null) {
                resultMap[type] = bucket.docCount()
            }
        }

        return resultMap
    }

    private fun baseSortQuery() =
        SortOptions.of {
            it.field { f ->
                f.field("updatedTime")
                f.order(SortOrder.Desc)
            }
            it.field { f2 ->
                f2.field("createdTime")
                f2.order(SortOrder.Desc)
            }
        }

    private fun searchAfterSortQuery(): List<SortOptions> =
        listOf(
            SortOptions.of { it.field { f -> f.field("updatedTime").order(SortOrder.Desc) } },
            SortOptions.of { it.field { f -> f.field("createdTime").order(SortOrder.Desc) } },
            // Use _shard_doc instead of _id (ES 8.x disallows _id fielddata by default)
            SortOptions.of { it.field { f -> f.field("_shard_doc").order(SortOrder.Asc) } },
        )

    private fun keywordSortQuery(type: Type) =
        SortOptions.of {
            it.field { f ->
                f.field(getSortFieldForType(type))
                f.order(SortOrder.Asc)
            }
        }

    private fun keywordSearchAfterSortQuery(type: Type): List<SortOptions> =
        listOf(
            SortOptions.of { it.field { f -> f.field(getSortFieldForType(type)).order(SortOrder.Asc) } },
            SortOptions.of { it.field { f -> f.field("_shard_doc").order(SortOrder.Asc) } },
        )

    private fun getSortFieldForType(type: Type): String =
        when (type) {
            Type.SYNONYM, Type.COMPOUND, Type.UNIT_SYNONYM -> "value.raw"
            else -> "keyword"
        }

    companion object {
        const val DICTIONARY_INDEX = ".dsearch_dict"
    }
}

package com.cowave.search.common.elasticsearch

import co.elastic.clients.elasticsearch.ElasticsearchClient
import co.elastic.clients.json.jackson.JacksonJsonpMapper
import co.elastic.clients.transport.rest5_client.Rest5ClientTransport
import co.elastic.clients.transport.rest5_client.low_level.Rest5Client
import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.databind.SerializationFeature
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule
import com.fasterxml.jackson.module.kotlin.kotlinModule
import jakarta.annotation.PreDestroy
import org.apache.hc.core5.http.Header
import org.apache.hc.core5.http.HttpHost
import org.apache.hc.core5.http.message.BasicHeader
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Component
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap

/**
 * 멀티 클러스터 Elasticsearch 클라이언트 팩토리.
 *
 * - ConcurrentHashMap 기반 클라이언트 캐시
 * - 클러스터 등록/삭제 시 캐시 갱신
 * - Basic 인증 및 ApiKey 인증 지원
 */
@Component
class ElasticsearchClientFactory {
    private val logger = LoggerFactory.getLogger(ElasticsearchClientFactory::class.java)

    private val clientCache = ConcurrentHashMap<String, CachedClusterClient>()

    private val jsonpMapper by lazy {
        val objectMapper =
            ObjectMapper()
                .registerModule(kotlinModule())
                .registerModule(JavaTimeModule())
                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
        JacksonJsonpMapper(objectMapper)
    }

    fun getClient(clusterId: String): ElasticsearchClient =
        clientCache[clusterId]?.esClient
            ?: throw IllegalArgumentException("등록되지 않은 클러스터입니다: $clusterId")

    fun getLowLevelClient(clusterId: String): Rest5Client =
        clientCache[clusterId]?.restClient
            ?: throw IllegalArgumentException("등록되지 않은 클러스터입니다: $clusterId")

    fun registerCluster(info: ClusterConnectionInfo) {
        val cached = buildCachedClient(info)
        clientCache[info.id] = cached
        logger.info("ES 클러스터 등록: {} ({}://{}:{})", info.id, info.scheme, info.host, info.port)
    }

    fun evictCluster(clusterId: String) {
        clientCache.remove(clusterId)?.let {
            runCatching { it.restClient.close() }
                .onFailure { e -> logger.warn("클러스터 클라이언트 종료 실패: $clusterId", e) }
        }
        logger.info("ES 클러스터 제거: {}", clusterId)
    }

    fun registeredClusterIds(): Set<String> = clientCache.keys.toSet()

    @PreDestroy
    fun closeAll() {
        clientCache.values.forEach { runCatching { it.restClient.close() } }
        clientCache.clear()
        logger.info("모든 ES 클러스터 클라이언트 종료 완료")
    }

    private fun buildCachedClient(info: ClusterConnectionInfo): CachedClusterClient {
        val host = HttpHost.create("${info.scheme}://${info.host}:${info.port}")
        val defaultHeaders = buildAuthHeaders(info)

        val restClient =
            Rest5Client
                .builder(host)
                .setDefaultHeaders(defaultHeaders)
                .build()

        val transport = Rest5ClientTransport(restClient, jsonpMapper)
        val esClient = ElasticsearchClient(transport)

        return CachedClusterClient(restClient, esClient)
    }

    private fun buildAuthHeaders(info: ClusterConnectionInfo): Array<Header> =
        when {
            !info.apiKey.isNullOrBlank() -> {
                arrayOf(BasicHeader("Authorization", "ApiKey ${info.apiKey}"))
            }
            !info.username.isNullOrBlank() && !info.password.isNullOrBlank() -> {
                val credentials = Base64.getEncoder().encodeToString("${info.username}:${info.password}".toByteArray())
                arrayOf(BasicHeader("Authorization", "Basic $credentials"))
            }
            else -> emptyArray()
        }

    private data class CachedClusterClient(
        val restClient: Rest5Client,
        val esClient: ElasticsearchClient,
    )

    data class ClusterConnectionInfo(
        val id: String,
        val scheme: String,
        val host: String,
        val port: Int,
        val username: String? = null,
        val password: String? = null,
        val apiKey: String? = null,
    )
}

package com.cowave.search.cluster.model

import org.bson.types.ObjectId
import org.springframework.data.annotation.Id
import org.springframework.data.mongodb.core.mapping.Document
import java.time.Instant

@Document(collection = "clusters")
data class Cluster(
    @Id
    val id: String = ObjectId.get().toHexString(),
    var name: String,
    var scheme: String = "http",
    var host: String,
    var port: Int,
    var kibana: String? = null,
    var theme: String? = null,
    var username: String? = null,
    var password: String? = null,
    var dictionaryRemoteClusterId: String? = null,
    var autocompleteUrl: String? = null,
    val createdAt: Instant = Instant.now(),
    var updatedAt: Instant = Instant.now(),
)

