import org.springframework.web.bind.annotation.ResponseStatus
import org.springframework.web.bind.annotation.RestController
import org.springframework.web.multipart.MultipartFile

@RestController
@RequestMapping("/dictionaries")
class DictionaryController(
    private val dictionaryService: DictionaryService,
) {
    /**
     * 사전 조회/검색 통합 API
     * - word가 없으면 전체 조회
     * - word가 있으면 검색 (searchColumn에 따라 대상 필드 결정)
     */
    @GetMapping("/{type}")
    fun getDictionary(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable type: Type,
        @RequestParam(defaultValue = "20") size: Int,
        @RequestParam(required = false) cursor: String?,
        @RequestParam(defaultValue = "UPDATED") sort: SortType,
        @RequestParam(defaultValue = "ALL") searchColumn: SearchColumn,
        @RequestParam(required = false) word: String?,
        @RequestParam(defaultValue = "false") isMatch: Boolean,
    ): CursorPagedResponse<Dictionary> =
        dictionaryService.search(
            clusterId = clusterId,
            type = type,
            size = size,
            searchColumn = searchColumn,
            word = word,
            isMatch = isMatch,
            cursor = cursor,
            sortType = sort,
        )

    @GetMapping("/{type}/count")
    fun countByType(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable type: Type,
    ): TypeCountResponse = TypeCountResponse(type, dictionaryService.countByType(clusterId, type))

    @GetMapping("/{type}/last-modified")
    fun getLastModifiedByType(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable type: Type,
    ): TypeLastModifiedResponse = dictionaryService.getLastModifiedByType(clusterId, type)

    @GetMapping("/last-modified")
    fun getAllTypesLastModified(
        @RequestHeader("cluster-id") clusterId: String,
    ): AllTypesLastModifiedResponse = dictionaryService.getAllTypesLastModified(clusterId)

    @GetMapping("/count")
    fun getAllTypesCounts(
        @RequestHeader("cluster-id") clusterId: String,
    ): AllTypesCountResponse = dictionaryService.getAllTypesCounts(clusterId)

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    fun create(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestBody request: CreateDictionaryRequest,
    ) {
        dictionaryService.create(clusterId, request.keyword, request.type, request.value)
    }

    @PutMapping("/{id}")
    fun update(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable id: String,
        @RequestBody request: UpdateDictionaryRequest,
    ) {
        dictionaryService.update(clusterId, id, request.keyword, request.type, request.value)
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun delete(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable id: String,
    ) {
        dictionaryService.delete(clusterId, id)
    }

    @PostMapping("/compile/{type}")
    fun compile(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable type: Type,
    ): CompileResult = dictionaryService.compile(clusterId, type)

    @PostMapping("/compile")
    fun compileAll(
        @RequestHeader("cluster-id") clusterId: String,
    ): List<CompileResult> = dictionaryService.compileAll(clusterId)

    // ── ROADMAP 2-2 추가 엔드포인트 ─────────────────────────────────────

    @PostMapping("/{type}/fileUpload")
    fun fileUpload(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable type: Type,
        @RequestParam("file") file: MultipartFile,
    ): ResponseEntity<Map<String, Any>> {
        val count = dictionaryService.fileUpload(clusterId, type, file)
        return ResponseEntity.ok(mapOf("count" to count, "result" to "OK"))
    }

    @GetMapping("/{type}/download")
    fun download(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable type: Type,
    ): ResponseEntity<ByteArray> {
        val content = dictionaryService.downloadAll(clusterId, type)
        val headers =
            HttpHeaders().apply {
                contentType = MediaType.TEXT_PLAIN
                setContentDispositionFormData("attachment", "${type.name.lowercase()}.txt")
            }
        return ResponseEntity.ok().headers(headers).body(content.toByteArray(Charsets.UTF_8))
    }

    @DeleteMapping("/resetDict/{type}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun resetDict(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable type: Type,
    ) {
        dictionaryService.resetDict(clusterId, type)
    }

    @GetMapping("/settings")
    fun getSettings(
        @RequestHeader("cluster-id") clusterId: String,
    ): List<DictionarySetting> = dictionaryService.getSettings(clusterId)

    @GetMapping("/applyHistory")
    fun getApplyHistory(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestParam(defaultValue = "20") size: Int,
    ): List<DictApplyHistory> = dictionaryService.getApplyHistory(clusterId, size)
}

