import com.cowave.search.template.dto.PutIndexTemplateRequest
import com.cowave.search.template.service.TemplateService
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.DeleteMapping
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PutMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestHeader
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/templates")
class TemplateController(
    private val templateService: TemplateService,
) {
    // ── Composable Index Template ─────────────────────────────────────────

    @GetMapping
    fun listIndexTemplates(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestParam(required = false) name: String?,
        @RequestParam(defaultValue = "true") excludeSystem: Boolean,
    ): List<IndexTemplateInfo> = templateService.listIndexTemplates(clusterId, name, excludeSystem)

    @GetMapping("/{name}")
    fun getIndexTemplate(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable name: String,
    ): ResponseEntity<IndexTemplateInfo> {
        val template = templateService.getIndexTemplate(clusterId, name)
        return if (template != null) ResponseEntity.ok(template) else ResponseEntity.notFound().build()
    }

    @PutMapping("/{name}")
    fun putIndexTemplate(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable name: String,
