package com.cowave.search.documentanalysis.service

import co.elastic.clients.elasticsearch._types.FieldValue
import co.elastic.clients.elasticsearch._types.SortOrder
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.documentanalysis.dto.ExecuteQueryRequest
import com.cowave.search.documentanalysis.dto.ExecuteQueryResponse
import com.cowave.search.documentanalysis.dto.FieldStatistics
import com.cowave.search.documentanalysis.dto.FieldTermVector
import com.cowave.search.documentanalysis.dto.SaveQueryRequest
import com.cowave.search.documentanalysis.dto.SavedQuery
import com.cowave.search.documentanalysis.dto.TermInfo
import com.cowave.search.documentanalysis.dto.TermVectorRequest
import com.cowave.search.documentanalysis.dto.TermVectorResponse
import com.cowave.search.documentanalysis.dto.TokenInfo
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import java.time.Instant

@Service
class DocumentAnalysisService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(DocumentAnalysisService::class.java)

    // ── Term Vector 분석 ──────────────────────────────────────────────────

    fun getTermVector(
        clusterId: String,
        request: TermVectorRequest,
    ): TermVectorResponse {
        val client = clientFactory.getClient(clusterId)

        val response =
            client.termvectors(
                co.elastic.clients.elasticsearch.core.TermvectorsRequest.of<Map<*, *>> { req ->
                    req.index(request.index)
                        .termStatistics(request.termStatistics)
                        .fieldStatistics(request.fieldStatistics)
                        .positions(request.positions)
                        .offsets(request.offsets)
                        .payloads(request.payloads)
                        .apply {
                            request.id?.let { id(it) }
                            request.fields?.let { fields(it) }
                        }
                },
                Map::class.java,
            )

        val termVectors =
            response.termVectors().mapValues { (_, fieldVector) ->
                val fieldStats =
                    fieldVector.fieldStatistics()?.let { fs ->
                        FieldStatistics(
                            docCount = fs.docCount().toLong(),
                            sumDocFreq = fs.sumDocFreq(),
                            sumTtf = fs.sumTtf(),
                        )
                    }
                val terms =
                    fieldVector.terms().mapValues { (_, termStats) ->
                        val tokens =
                            termStats.tokens().map { token ->
                                TokenInfo(
                                    position = token.position(),
                                    startOffset = token.startOffset(),
                                    endOffset = token.endOffset(),
                                    payload = token.payload(),
                                )
                            }
                        TermInfo(
                            docFreq = termStats.docFreq()?.toLong(),
                            ttf = termStats.ttf()?.toLong(),
                            termFreq = termStats.termFreq().toLong(),
                            score = termStats.score(),
                            tokens = tokens,
                        )
                    }
                FieldTermVector(fieldStatistics = fieldStats, terms = terms)
            }

        return TermVectorResponse(
            index = response.index(),
            id = response.id(),
            found = response.found(),
            termVectors = termVectors,
        )
    }

    // ── 검색 쿼리 저장 (dsearch-analysis-query 인덱스) ────────────────────

    fun saveQuery(
        clusterId: String,
        request: SaveQueryRequest,
    ): String {
        val client = clientFactory.getClient(clusterId)
        val query =
            SavedQuery(
                id = null,
                name = request.name,
                description = request.description,
                index = request.index,
                query = request.query,
            )
        val response = client.index { it.index(ANALYSIS_QUERY_INDEX).document(query) }
        logger.info("검색 쿼리 저장 [{}/{}]: {}", clusterId, response.id(), request.name)
        return response.id()
    }

    fun listSavedQueries(
        clusterId: String,
        size: Int = 20,
        searchAfterValues: List<String>? = null,
    ): List<SavedQuery> {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response =
                client.search(
                    { s ->
                        s.index(ANALYSIS_QUERY_INDEX)
                            .size(size)
                            .sort { so -> so.field { f -> f.field("updatedAt").order(SortOrder.Desc) } }
                            .apply {
                                searchAfterValues?.let { sa ->
                                    searchAfter(sa.map { FieldValue.of(it) })
                                }
                            }
                    },
                    SavedQuery::class.java,
                )
            response.hits().hits().mapNotNull { hit ->
                hit.source()?.copy(id = hit.id())
            }
        }.getOrElse { e ->
            logger.warn("저장된 쿼리 목록 조회 실패 [{}]: {}", clusterId, e.message)
            emptyList()
        }
    }

    fun getSavedQuery(
        clusterId: String,
        id: String,
