import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import java.time.Instant

@Service
class DocumentAnalysisService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(DocumentAnalysisService::class.java)

    // ── Term Vector 분석 ──────────────────────────────────────────────────

    fun getTermVector(
        clusterId: String,
        request: TermVectorRequest,
    ): TermVectorResponse {
        val client = clientFactory.getClient(clusterId)

        val response =
            client.termvectors(
                co.elastic.clients.elasticsearch.core.TermvectorsRequest.of<Map<*, *>> { req ->
                    req.index(request.index)
                        .termStatistics(request.termStatistics)
                        .fieldStatistics(request.fieldStatistics)
                        .positions(request.positions)
                        .offsets(request.offsets)
                        .payloads(request.payloads)
                        .apply {
                            request.id?.let { id(it) }
                            request.fields?.let { fields(it) }
                        }
                },
                Map::class.java,
            )

        val termVectors =
            response.termVectors().mapValues { (_, fieldVector) ->
                val fieldStats =
                    fieldVector.fieldStatistics()?.let { fs ->
                        FieldStatistics(
                            docCount = fs.docCount().toLong(),
                            sumDocFreq = fs.sumDocFreq(),
                            sumTtf = fs.sumTtf(),
                        )
                    }
                val terms =
                    fieldVector.terms().mapValues { (_, termStats) ->
                        val tokens =
                            termStats.tokens().map { token ->
                                TokenInfo(
                                    position = token.position(),
                                    startOffset = token.startOffset(),
                                    endOffset = token.endOffset(),
                                    payload = token.payload(),
                                )
                            }
                        TermInfo(
                            docFreq = termStats.docFreq()?.toLong(),
                            ttf = termStats.ttf()?.toLong(),
                            termFreq = termStats.termFreq().toLong(),
                            score = termStats.score(),
                            tokens = tokens,
                        )
                    }
                FieldTermVector(fieldStatistics = fieldStats, terms = terms)
            }

        return TermVectorResponse(
            index = response.index(),
            id = response.id(),
            found = response.found(),
            termVectors = termVectors,
