package com.cowave.search.pipeline.service

import co.elastic.clients.elasticsearch.ingest.Document
import co.elastic.clients.elasticsearch.ingest.Processor
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.pipeline.dto.PipelineInfo
import com.cowave.search.pipeline.dto.ProcessorResult
import com.cowave.search.pipeline.dto.PutPipelineRequest
import com.cowave.search.pipeline.dto.SimulateDocResult
import com.cowave.search.pipeline.dto.SimulatePipelineRequest
import com.cowave.search.pipeline.dto.SimulatePipelineResponse
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

@Service
class PipelineService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(PipelineService::class.java)

    fun listPipelines(
        clusterId: String,
        id: String? = null,
    ): List<PipelineInfo> {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response = client.ingest().getPipeline { req -> id?.let { req.id(it) } ?: req }
            response.pipelines().map { (pipelineId, pipeline) ->
                val processors =
                    pipeline.processors().map { proc ->
                        mapOf("type" to proc._kind().jsonValue())
                    }
                PipelineInfo(
                    id = pipelineId,
                    description = pipeline.description(),
                    version = pipeline.version(),
                    processors = processors,
                )
            }
        }.getOrElse { e ->
            logger.warn("파이프라인 목록 조회 실패 [{}]: {}", clusterId, e.message)
            emptyList()
        }
    }

    fun getPipeline(
        clusterId: String,
        id: String,
    ): PipelineInfo? {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response = client.ingest().getPipeline { it.id(id) }
            response.pipelines()[id]?.let { pipeline ->
                PipelineInfo(
                    id = id,
                    description = pipeline.description(),
                    version = pipeline.version(),
                    processors = pipeline.processors().map { mapOf("type" to it._kind().jsonValue()) },
                )
            }
        }.getOrElse { e ->
            logger.warn("파이프라인 조회 실패 [{}/{}]: {}", clusterId, id, e.message)
            null
        }
    }

    fun putPipeline(
        clusterId: String,
        id: String,
        request: PutPipelineRequest,
    ) {
        val client = clientFactory.getClient(clusterId)
        val mapper = com.fasterxml.jackson.databind.ObjectMapper()

        client.ingest().putPipeline { req ->
            req.id(id)
                .apply {
                    request.description?.let { description(it) }
                    request.version?.let { version(it) }
                    if (request.processors.isNotEmpty()) {
                        processors(
                            request.processors.map { procMap ->
                                val procJson = mapper.writeValueAsString(procMap)
                                Processor.of { p ->
                                    p.withJson(java.io.StringReader(procJson))
                                }
                            },
                        )
                    }
                }
        }
        logger.info("파이프라인 저장: {}/{}", clusterId, id)
    }

    fun deletePipeline(
        clusterId: String,
        id: String,
    ) {
        val client = clientFactory.getClient(clusterId)
        client.ingest().deletePipeline { it.id(id) }
        logger.info("파이프라인 삭제: {}/{}", clusterId, id)
    }

    fun simulatePipeline(
        clusterId: String,
        pipelineId: String?,
        request: SimulatePipelineRequest,
    ): SimulatePipelineResponse {
        val client = clientFactory.getClient(clusterId)
        val mapper = com.fasterxml.jackson.databind.ObjectMapper()

        // ES 9.x: client.simulate().ingest() API 사용
        val docs =
            request.docs.map { doc ->
                val sourceJson = mapper.writeValueAsString(doc.source)
                Document.of { d ->
                    d.index(doc.index)
                        .apply { doc.id?.let { id(it) } }
                        .withJson(java.io.StringReader(sourceJson))
                }
            }

        val response =
            client.simulate().ingest { req ->
                pipelineId?.let { req.pipeline(it) }
                req.docs(docs)
            }

        val results =
            response.docs().map { docResult ->
                val error = docResult.doc()?.error()
                if (error != null) {
                    SimulateDocResult(
                        docId = docResult.doc()?.id(),
                        index = docResult.doc()?.index(),
                        source = emptyMap(),
                        error = error.reason(),
                    )
                } else {
                    @Suppress("UNCHECKED_CAST")
                    val source = docResult.doc()?.source()?.mapValues { (_, v) -> v.to(Any::class.java) } ?: emptyMap()
                    SimulateDocResult(
                        docId = docResult.doc()?.id(),
                        index = docResult.doc()?.index(),
                        source = source,
                        processorResults = emptyList(),
                    )
                }
            }

        return SimulatePipelineResponse(docs = results)
    }
}

