        val client = clientFactory.getClient(clusterId)
        val mapper = com.fasterxml.jackson.databind.ObjectMapper()

        // ES 9.x: client.simulate().ingest() API 사용
        val docs =
            request.docs.map { doc ->
                val sourceJson = mapper.writeValueAsString(doc.source)
                Document.of { d ->
                    d.index(doc.index)
